<?php if($note['corrections_status']!=='unknown'): ?><div class="table-scroll" tabindex="0" role="region" aria-label="<?= $escape($taxText('Tabelle mit Steuerangaben')) ?>"><table class="table"><thead><tr><th><?= $escape($taxText('Sphäre')) ?></th><th><?= $escape($taxText('Zahlungsergebnis')) ?></th><th><?= $escape($taxText('Korrekturen')) ?></th><th><?= $escape($taxText('Ergebnis der Arbeitsrechnung')) ?></th></tr></thead><tbody><?php foreach($annual['spheres'] as $s): if(!in_array($s['key'],['1','2','3','4'],true))continue;$change=0;foreach($note['corrections'] as $c)if($c['sphere']===$s['key'])$change+=($c['direction']==='add'?1:-1)*$c['amount_cents']; ?><tr><td><?= $escape($s['key'].' · '.$s['label']) ?></td><td><?= $money($s['result_cents']) ?></td><td><?= $money($change) ?></td><td><?= $money($s['result_cents']+$change) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
